<template>
  <div class="fence-page">
    <BaseMap ref="baseMapRef" />
    <div class="fence-panel">
      <div class="panel-card"><div class="panel-title">青贮数字围栏·种植上图</div><div class="stats"><div><b>{{ fences.length }}</b><span>备案围栏</span></div><div><b>{{ totalArea.toFixed(1) }}</b><span>围栏面积（亩）</span></div><div><b>{{ geoCount }}</b><span>关联地块</span></div></div><el-button type="primary" class="draw-btn" @click="startDraw">新增种植地块 / 地图勾绘</el-button><div v-if="drawing" class="draw-tools"><el-button size="small" type="primary" @click="finishDraw">完成勾绘</el-button><el-button size="small" @click="drawApi?.clear()">清除点位</el-button><el-button size="small" @click="cancelDraw">取消</el-button></div><div v-if="drawing" class="draw-tip">请依次点击地图绘制多边形，至少 3 个点</div></div>
      <div class="panel-card list-card"><div class="panel-title">围栏列表</div><el-input v-model="keyword" clearable placeholder="搜索备案编号或主体" class="fence-search"/><div v-for="f in filteredFences" :key="f.id" class="fence-item" @click="locate(f)"><div><b>{{ f.filedNo }}</b><p>{{ f.subjectName }}</p><small>{{ cropName(f.crop) }} · {{ f.createdAt }}</small></div><el-button link type="primary">定位</el-button></div><el-empty v-if="!filteredFences.length" description="暂无数字围栏" /></div>
    </div>
    <el-drawer v-model="drawerVisible" :title="current?.filedNo || '围栏详情'" size="420px"><template v-if="current"><el-descriptions :column="1" border><el-descriptions-item label="备案编号">{{ current.filedNo }}</el-descriptions-item><el-descriptions-item label="备案主体">{{ current.subjectName }}</el-descriptions-item><el-descriptions-item label="种植品种">{{ cropName(current.crop) }}</el-descriptions-item><el-descriptions-item label="备案日期">{{ current.createdAt }}</el-descriptions-item><el-descriptions-item label="关联地块">{{ currentGeo.features?.length || 0 }} 块</el-descriptions-item><el-descriptions-item label="围栏面积">{{ currentArea.toFixed(1) }} 亩</el-descriptions-item></el-descriptions><div class="sub-title">围栏内地块</div><el-table :data="currentGeo.features || []" size="small" border><el-table-column prop="properties.plotName" label="地块名称" min-width="160"/><el-table-column prop="properties.plotId" label="地块编号" width="110"/><el-table-column prop="properties.areaMu" label="面积（亩）" width="90"/></el-table><div class="drawer-actions"><el-button type="primary" size="small" @click="locate(current)">重新定位</el-button></div></template></el-drawer>
    <el-dialog v-model="formVisible" title="保存地图勾绘地块" width="520px"><el-form :model="form" label-width="100px"><el-form-item label="主体" required><el-input v-model="form.subjectName" disabled /></el-form-item><el-form-item label="品种" required><el-select v-model="form.crop" style="width:100%"><el-option label="青贮玉米" value="silage_corn"/><el-option label="苜蓿" value="alfalfa"/></el-select></el-form-item><el-form-item label="地块名称"><el-input v-model="form.plotName" placeholder="自绘地块"/></el-form-item><el-form-item label="面积（亩）" required><el-input-number v-model="form.areaMu" :min="0" :precision="1" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="cancelDraw">取消</el-button><el-button type="primary" @click="saveDraw">保存地块/围栏</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import BaseMap from '@/components/map/BaseMap.vue'
import { fetchFences, fetchFenceGeoJSON, saveFencePlot } from '@/api/sil'
import { polygonAreaMu } from '@/map/geoUtils'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const baseMapRef = ref(null); const fences = ref([]); const geoMap = ref({}); const current = ref(null); const drawerVisible = ref(false); const formVisible = ref(false); const drawing = ref(false); const keyword = ref(''); const drawApi = ref(null); const geometry = ref(null)
const form = ref({ subjectId: '', subjectName: '', crop: 'silage_corn', plotName: '', areaMu: 0 }); const filteredFences = computed(() => fences.value.filter((f) => !keyword.value || `${f.filedNo}${f.subjectName}`.includes(keyword.value))); const geoCount = computed(() => Object.values(geoMap.value).reduce((s, g) => s + (g.features?.length || 0), 0)); const totalArea = computed(() => Object.values(geoMap.value).reduce((s, g) => s + (g.features || []).reduce((a, f) => a + Number(f.properties?.areaMu || 0), 0), 0)); const currentGeo = computed(() => current.value ? geoMap.value[current.value.id] || { features: [] } : { features: [] }); const currentArea = computed(() => (currentGeo.value.features || []).reduce((s, f) => s + Number(f.properties?.areaMu || 0), 0)); const cropName = (c) => ({ silage_corn: '青贮玉米', alfalfa: '苜蓿' }[c] || c)
const locate = (f) => { current.value = f; drawerVisible.value = true; const feature = geoMap.value[f.id]?.features?.[0]; if (feature) { const [lng, lat] = feature.geometry.coordinates[0][0]; baseMapRef.value?.flyTo([lat, lng], 12) } }
const load = async () => { fences.value = await fetchFences(userStore.role); const entries = await Promise.all(fences.value.map(async (f) => [f.id, await fetchFenceGeoJSON(f)])); geoMap.value = Object.fromEntries(entries); const features = entries.flatMap(([, geo]) => geo.features || []); baseMapRef.value?.addGeoJSON('silFences', { type: 'FeatureCollection', features }, { style: { color: '#26a69a', weight: 2, fillColor: '#26a69a', fillOpacity: 0.3 }, onEachFeature: (feature, layer) => layer.on('click', () => locate(fences.value.find((f) => f.id === feature.properties.fenceId))) }) }
const startDraw = () => { if (!userStore.role?.subjectId) return ElMessage.warning('请切换到种植主体角色后新增地块'); drawing.value = true; drawApi.value?.stop(); drawApi.value = baseMapRef.value?.startPolygonDraw({ onFinish: (geo) => { geometry.value = geo; form.value = { subjectId: userStore.role.subjectId, subjectName: userStore.role.name ? userStore.role.unit : '', crop: 'silage_corn', plotName: '', areaMu: polygonAreaMu(geo.coordinates[0]) }; formVisible.value = true; drawing.value = false } }) }
const finishDraw = () => {
  const result = drawApi.value?.finish()
  if (!result) ElMessage.warning('至少需要绘制3个点')
}
const cancelDraw = () => { drawApi.value?.stop(); drawApi.value = null; geometry.value = null; drawing.value = false; formVisible.value = false }
const saveDraw = async () => { if (!geometry.value || !form.value.areaMu) return ElMessage.warning('请完成绘制并填写面积'); const result = await saveFencePlot({ ...form.value, geometry: geometry.value, cropName: cropName(form.value.crop) }, userStore.role); if (!result.success) return ElMessage.error(result.message || '保存失败'); ElMessage.success('地块和围栏已保存'); cancelDraw(); await load() }
onMounted(() => setTimeout(load, 300))
</script>
<style scoped lang="scss">.fence-page{position:relative;height:100%;min-height:620px;overflow:hidden}.fence-panel{position:absolute;z-index:500;top:16px;left:16px;width:350px;max-height:calc(100% - 32px);overflow:auto}.panel-card{margin-bottom:12px;padding:14px;background:rgba(255,255,255,.95);border:1px solid #dce6f0;border-radius:10px;box-shadow:0 4px 16px rgba(40,70,100,.15)}.panel-title{font-weight:700;color:#24476c;margin-bottom:12px}.stats{display:flex;justify-content:space-between;text-align:center}.stats b{display:block;color:#168c86;font-size:22px}.stats span{font-size:11px;color:#7b8794}.draw-btn{width:100%;margin-top:14px}.draw-tip{margin-top:8px;color:#168c86;font-size:12px}.fence-search{margin-bottom:8px}.fence-item{display:flex;justify-content:space-between;gap:8px;padding:10px 2px;border-top:1px solid #edf1f5;cursor:pointer}.fence-item b{font-size:12px;color:#168c86}.fence-item p{margin:4px 0;font-size:13px;color:#354b63}.fence-item small{color:#8b98a8}.sub-title{margin:16px 0 8px;padding-left:8px;border-left:3px solid #168c86;font-weight:600}.drawer-actions{margin-top:14px}</style>
